def read_record(records, actor, record_id):
    row = records.get(record_id)
    allowed = lambda owner: owner == actor["id"]
    return row if row is not None and allowed(row["owner_id"]) else None

records = {10: {'owner_id': 'u1', 'tenant_id': 'same', 'members': ['u1'], 'secret': 'owned'}, 20: {'owner_id': 'u2', 'tenant_id': 'same', 'members': ['u2'], 'secret': 'other'}}
actor = {'id': 'u1', 'tenant_id': 'same', 'role': 'member', 'authenticated': True}
Independently evaluate read_record(records, actor, 10), read_record(records, actor, 20), and read_record(records, actor, 99).
